#!/usr/bin/env python3
"""Build an offline read-only dashboard from the executable three-module JSON output."""
from pathlib import Path
import json, html
base=Path(__file__).resolve().parents[4]
r=json.loads((base/'shared_exchange/three-module-results.json').read_text(encoding='utf8'))
out=base/'medrep_coach_with_ai_rules/module2/demo/three-modules/index.html'
out.parent.mkdir(parents=True,exist_ok=True)
# Avoid injecting source text as executable HTML/JS.
payload=json.dumps(r,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
page='''<!DOCTYPE html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MedRep Coach｜三模块真实数据流实验台</title>
<style>:root{color-scheme:light;font-family:system-ui,-apple-system,"PingFang SC","Microsoft Yahei",sans-serif;color:#152537;background:#f4f7fa}*{box-sizing:border-box}body{margin:0}.page{max-width:1120px;margin:auto;padding:30px 22px}header{padding:26px;background:#143855;color:white;border-radius:16px}h1{font-size:26px;margin:0 0 9px}h2{font-size:20px}p{line-height:1.75}header p{opacity:.9;margin:0}.tag{font-size:12px;background:#fff1cf;border:1px solid #f2ca72;color:#795307;border-radius:5px;padding:3px 7px;margin-left:5px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:18px 0}.metric,.panel,.step{background:#fff;border:1px solid #d8e3eb;border-radius:12px}.metric{padding:15px}.metric strong{font-size:21px;display:block;color:#154979}.metric small{color:#647588}.layout{display:grid;grid-template-columns:245px 1fr;gap:16px}.rail{display:grid;gap:8px;align-content:start}.step{padding:13px;text-align:left;cursor:pointer;font:inherit}.step.active{border-color:#3178bd;background:#e9f4ff;color:#0b4776;font-weight:700}.panel{padding:20px;min-height:470px}.line{padding:12px 14px;border-radius:9px;margin:10px 0;background:#f5f8fa;border:1px solid #e6eef3}.label{font-size:12px;letter-spacing:.04em;font-weight:700;color:#52708c}.main-value{font-size:18px;font-weight:650;margin-top:4px;overflow-wrap:anywhere}.notice{background:#fff5dd;border-left:4px solid #cd8a20;padding:14px;margin-top:18px;font-size:14px}.small{font-size:13px;color:#667b8c}.flow{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}.flow span{background:#edf5fb;color:#285c7d;border:1px solid #d1e1f0;padding:8px 10px;border-radius:7px}.json{background:#132b42;color:#deedf6;border-radius:9px;padding:15px;white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.6}button{cursor:pointer}a{color:#1260a5}@media(max-width:720px){.metrics{grid-template-columns:repeat(2,1fr)}.layout{grid-template-columns:1fr}.rail{grid-template-columns:repeat(2,1fr)}} </style></head><body><div class="page"><header><h1>三个模块现在到底怎么协作？</h1><p>这不是规划图，而是本次已执行的源代码数据流。每一步都能追到实际生成的 JSON 文件。<span class="tag">虚构数据 · 离线测试</span></p></header>
<div class="metrics"><div class="metric"><strong>3 个模块</strong><small>各自代码参与测试</small></div><div class="metric"><strong>5 类资产</strong><small>模块 2 生成长期证据</small></div><div class="metric"><strong>1 条资料线索</strong><small>模块 3 检索到待审核示例</small></div><div class="metric"><strong>1 个选题变化</strong><small>只是候选，还未正式执行</small></div></div>
<div class="layout"><nav class="rail" id="rail"></nav><section class="panel"><h2 id="title"></h2><p id="explain"></p><div id="details"></div><div class="notice" id="warning"></div><details><summary class="small" style="cursor:pointer;margin-top:18px">查看这一阶段的实际 JSON</summary><pre class="json" id="raw"></pre></details></section></div>
<p class="small">本页面由 <code>shared_exchange/three-module-results.json</code> 自动生成；没有 API 密钥、真实用户数据或联网模型输出。模块 1 正式准备函数尚未接受候选，模块 3 检索为本地示例，真实三服务上线尚未完成。</p></div>
<script>const r=__DATA__;
const steps=[
{title:'① 模块 3 发现外部资料',explain:'直接执行 MedRep Daily 的历史资讯样例筛选，输出有链接、有来源的学习候选。',data:()=>r.module3,details:()=>[['来源候选数',r.module3.sourceCandidates+' 条'],['查询后命中',r.module3.found.map(x=>x.title).join('；')||'未命中']],warning:'这是历史样例，不是今天联网抓到的资料；不能自动当成审核通过的医学知识。'},
{title:'② 模块 1 冻结拜访准备',explain:'从模块 1 的 Python 课程/场景源码导出，再通过模块 2 的校验器核实原计划和资料版本。',data:()=>r.module1,details:()=>[['课程',r.module1.lessonId],['冻结时已选',r.module1.selectedBefore.join(' ＋ ')],['冻结快照指纹',r.module1.snapshotHash.slice(0,20)+'…']],warning:'原计划只读取，不因拜访后的新发现修改过去的快照。训练结果是按模块1字段制造的虚构记录。'},
{title:'③ 两次训练与拜访进入模块 2',explain:'第一轮逐项评价显示缺口，第二轮满足该评价项；同时将现场问题锚定到复盘原话。',data:()=>({first:r.module2.firstPractice,second:r.module2.secondPractice,personal:r.module2.personal}),details:()=>[['第一次练习',r.module2.firstPractice[0].result],['第二次练习',r.module2.secondPractice[0].result],['个人能力当前建议',r.module2.personal.map(p=>p.status).join('、')]],warning:'作答评价是形成性证据，不等于医学审核或长期掌握。'},
{title:'④ 模块 2 生成五类长期证据',explain:'将同一份核验过的虚构拜访分别记入能力、预测差异、知识覆盖、专家观察和群体事件。',data:()=>({assets:r.module2.assets,knowledge:r.module2.knowledge,forecast:r.module2.forecast}),details:()=>[['资产类型', [...new Set(r.module2.assets.map(x=>x.kind))].join(' / ')],['知识检查结果',r.module2.knowledge.map(k=>k.recommendation).join('、')],['群体结论',r.module2.cohort.map(x=>x.status).join('、')]],warning:'一条拜访记录不会自动证明专家偏好，也不会形成公司级模式结论。'},
{title:'⑤ 模块 2 向模块 3 查资料',explain:'模块 2 把检索不到依据的线索发出；模块 3 用自己的资讯样例库查找，并把来源原封不动传回。',data:()=>r.module3,details:()=>[['检索主题',r.module3.query],['资料来源',r.module3.found.map(x=>x.id).join('、')],['处理状态',r.module3.searchStatus]],warning:'“检索到相关学习文章”不等于该篇文章能够补足 C-17 的具体研究证据，更不意味着知识库已更新。'},
{title:'⑥ 候选交还模块 1（未正式应用）',explain:'模块 2 把下一轮选题候选送回模块 1 的交换目录；模块 3 的文章另进入医学审核待办队列。',data:()=>({preparation:r.module2.nextPreparation,review:r.module3.reviewCandidates,exchanges:r.exchange}),details:()=>[['原选题',r.module2.nextPreparation.before.join(' ＋ ')],['新候选',r.module2.nextPreparation.after.join(' ＋ ')],['新增选题',r.module2.nextPreparation.added.join('、')],['被挤出的选题',r.module2.nextPreparation.displaced.join('、')],['是否已经写入正式准备单',r.module2.nextPreparation.status==='CANDIDATE_NOT_APPLIED'?'没有（待采纳）':'状态需核查']],warning:'模块 1 的 Engine.prepare() 尚未消费该候选；医学资料仍为待审核。当前联动是可运行的数据交换，不是生产服务自动闭环。'}
];
const escape=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
function show(i){document.querySelectorAll('.step').forEach((e,k)=>e.classList.toggle('active',i===k));const x=steps[i];document.getElementById('title').textContent=x.title;document.getElementById('explain').textContent=x.explain;document.getElementById('details').innerHTML=x.details().map(([k,v])=>'<div class="line"><div class="label">'+escape(k)+'</div><div class="main-value">'+escape(v||'无')+'</div></div>').join('');document.getElementById('warning').textContent=x.warning;document.getElementById('raw').textContent=JSON.stringify(x.data(),null,2);}
steps.forEach((s,i)=>{const b=document.createElement('button');b.className='step';b.textContent=s.title;b.addEventListener('click',()=>show(i));document.getElementById('rail').appendChild(b)});show(0);
</script></body></html>'''.replace('__DATA__',payload)
out.write_text(page,encoding='utf8')
print(out)
